package databasemonitor

const consoleHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Database Console</title>
<style>
:root{color-scheme:light;--ink:#17211f;--muted:#64716e;--line:#dce3e1;--soft:#f4f7f6;--teal:#087f72;--teal-soft:#dff3ef;--green:#067647;--green-soft:#dcfae6;--amber:#9a6400;--amber-soft:#fff1ca;--red:#b42318;--red-soft:#fee4e2;--white:#fff}*{box-sizing:border-box}body{margin:0;background:var(--soft);color:var(--ink);font:14px/1.45 Inter,Segoe UI,Arial,sans-serif;letter-spacing:0}button,input,select{font:inherit;letter-spacing:0}.topbar{height:58px;background:var(--white);border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;z-index:3}.brand{display:flex;align-items:center;gap:11px}.mark{width:28px;height:28px;border-radius:5px;background:var(--teal);color:#fff;display:grid;place-items:center;font-weight:700}.brand strong{font-size:15px}.brand small{display:block;color:var(--muted);font-size:11px}.actions,.controls{display:flex;align-items:center;gap:8px}.actions select,.actions button,.filter,.sort{height:34px;border:1px solid var(--line);border-radius:5px;background:#fff;color:var(--ink)}.actions button{padding:0 14px}.actions button,.sort-direction{cursor:pointer}.actions button:hover,.sort-direction:hover{border-color:var(--teal);color:var(--teal)}main{max-width:1600px;margin:0 auto;padding:22px 24px 42px}.summary{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));border:1px solid var(--line);background:#fff;border-radius:6px;overflow:hidden}.metric{padding:14px 16px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);min-height:76px}.metric:nth-child(5n){border-right:0}.metric:nth-last-child(-n+5){border-bottom:0}.metric span{display:block;color:var(--muted);font-size:12px;margin-bottom:5px}.metric strong{font-size:20px;font-weight:650}.tone{font-weight:650}.tone.good{color:var(--green)}.tone.warn{color:var(--amber)}.tone.bad{color:var(--red)}.tone.muted{color:var(--muted);font-weight:500}.tabs{display:flex;gap:2px;margin:18px 0 10px;border-bottom:1px solid var(--line);overflow-x:auto}.tab{border:0;border-bottom:2px solid transparent;background:transparent;padding:10px 14px;color:var(--muted);cursor:pointer;white-space:nowrap}.tab.active{color:var(--teal);border-bottom-color:var(--teal);font-weight:600}.view{display:none}.view.active{display:block}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.toolbar h2{font-size:14px;margin:0}.filter{width:min(340px,42vw);padding:0 10px}.sort{padding:0 30px 0 9px}.sort-direction{width:34px;height:34px;border:1px solid var(--line);border-radius:5px;background:#fff;font-size:17px}.table-wrap{background:#fff;border:1px solid var(--line);border-radius:6px;overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th{position:sticky;top:0;background:#f9fbfa;color:var(--muted);font-size:11px;text-transform:uppercase;text-align:left;padding:10px 12px;border-bottom:1px solid var(--line)}td{padding:10px 12px;border-bottom:1px solid #edf1f0}tr:last-child td{border-bottom:0}tbody tr:hover{background:#f8fbfa}.sql{max-width:620px;overflow:hidden;text-overflow:ellipsis;font-family:Consolas,monospace;font-size:12px}.sql-main-row{cursor:pointer}.sql-cell{display:flex;align-items:center;gap:8px;min-width:420px;max-width:680px}.disclosure{width:24px;height:24px;flex:0 0 24px;border:0;background:transparent;color:var(--muted);font-size:20px;line-height:1;cursor:pointer;transform:rotate(0deg);transition:transform .12s ease}.disclosure.open{transform:rotate(90deg)}.detail-row[hidden]{display:none}.detail-row td{padding:0;background:#f9fbfa}.detail-grid{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:0;border-top:1px solid var(--line)}.detail-item{padding:12px 14px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);min-width:0}.detail-item:nth-child(5n){border-right:0}.detail-item dt{color:var(--muted);font-size:11px;text-transform:uppercase;margin-bottom:4px}.detail-item dd{margin:0;overflow:hidden;text-overflow:ellipsis}.detail-wide{grid-column:span 2}.buckets{font-family:Consolas,monospace;font-size:11px;color:var(--muted)}.status{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:600}.dot{width:7px;height:7px;border-radius:50%;background:var(--muted)}.status.good{color:var(--green)}.status.good .dot{background:var(--green)}.status.warn{color:var(--amber)}.status.warn .dot{background:var(--amber)}.status.bad{color:var(--red)}.status.bad .dot{background:var(--red)}.badge{display:inline-block;border-radius:4px;padding:2px 6px;background:var(--teal-soft);color:var(--teal);font-size:11px;font-weight:700}.badge.write{background:var(--amber-soft);color:var(--amber)}.badge.success{background:var(--green-soft);color:var(--green)}.badge.failed{background:var(--red-soft);color:var(--red)}.empty{padding:34px;color:var(--muted);text-align:center}.error{display:none;margin-bottom:12px;border:1px solid #f7b4ae;background:var(--red-soft);color:var(--red);padding:10px 12px;border-radius:5px}.timestamp,.secondary{color:var(--muted);font-size:12px}@media(max-width:1100px){.summary{grid-template-columns:repeat(2,1fr)}.metric:nth-child(n){border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.metric:nth-child(2n){border-right:0}.metric:nth-last-child(-n+2){border-bottom:0}.detail-grid{grid-template-columns:repeat(2,minmax(130px,1fr))}.detail-item:nth-child(n){border-right:1px solid var(--line)}.detail-item:nth-child(2n){border-right:0}}@media(max-width:850px){.topbar{padding:0 12px}.brand small{display:none}main{padding:14px 12px 30px}.toolbar{align-items:flex-start;flex-direction:column}.controls{width:100%;flex-wrap:wrap}.filter{width:100%;flex-basis:100%}.sort{flex:1}.actions select{display:none}}@media(max-width:460px){.actions button{padding:0 9px}.tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;overflow:visible}.tab{padding:9px 6px}.sql-cell{min-width:300px}}
</style>
</head>
<body>
<header class="topbar"><div class="brand"><div class="mark">DB</div><div><strong>Database Console</strong><small>Runtime diagnostics</small></div></div><div class="actions"><select id="interval" aria-label="Refresh interval"><option value="0">Manual</option><option value="5000" selected>5 seconds</option><option value="15000">15 seconds</option><option value="60000">1 minute</option></select><button id="refresh" type="button">Refresh</button></div></header>
<main><div id="error" class="error" role="alert"></div><section class="summary"><div class="metric"><span>Datasource state</span><strong id="state">-</strong></div><div class="metric"><span>Open connections</span><strong id="open">0</strong></div><div class="metric"><span>Pool in use</span><strong id="inuse">0</strong></div><div class="metric"><span>Running SQL</span><strong id="running">0</strong></div><div class="metric"><span>Peak concurrency</span><strong id="peak">0</strong></div><div class="metric"><span>SQL fingerprints</span><strong id="tracked">0</strong></div><div class="metric"><span>Executions</span><strong id="executions">0</strong></div><div class="metric"><span>Errors</span><strong id="errors">0</strong></div><div class="metric"><span>Average latency</span><strong id="average">0 ms</strong></div><div class="metric"><span>Slow samples</span><strong id="slowcount">0</strong></div></section>
<nav class="tabs" aria-label="Database views"><button class="tab" data-view="pools">Connection Pools</button><button class="tab" data-view="operations">SQL Operations</button><button class="tab active" data-view="sql">SQL Statistics</button><button class="tab" data-view="slow">Slow SQL</button></nav>
<section id="pools" class="view"><div class="toolbar"><h2>Connection pools</h2><span id="checked" class="timestamp"></span></div><div class="table-wrap"><table><thead><tr><th>Datasource</th><th>Status</th><th>Roles</th><th>Open</th><th>In use</th><th>Idle</th><th>Max</th><th>Waits</th><th>Wait time</th><th>Failures</th></tr></thead><tbody id="poolRows"></tbody></table></div></section>
<section id="operations" class="view"><div class="toolbar"><h2>SQL operation statistics</h2><span id="operationMeta" class="secondary"></span></div><div class="table-wrap"><table><thead><tr><th>Datasource</th><th>Operation</th><th>Running</th><th>Peak</th><th>Executions</th><th>Successes</th><th>Errors</th><th>Min</th><th>Avg</th><th>Max</th><th>Total</th><th>Rows total/max</th><th>Latency buckets</th><th>First execution</th><th>Last execution</th></tr></thead><tbody id="operationRows"></tbody></table></div></section>
<section id="sql" class="view active"><div class="toolbar"><h2>SQL fingerprint statistics</h2><div class="controls"><input id="sqlFilter" class="filter" type="search" placeholder="Filter datasource, operation, table, or SQL"><select id="sqlSort" class="sort" aria-label="Sort SQL statistics"><option value="total_duration_ms">Total time</option><option value="executions">Executions</option><option value="errors">Errors</option><option value="average_duration_ms">Average time</option><option value="max_duration_ms">Slowest time</option><option value="minimum_duration_ms">Fastest time</option><option value="last_executed_at">Last execution</option></select><button id="sortDirection" class="sort-direction" type="button" title="Descending" aria-label="Descending">&#8595;</button></div></div><div class="table-wrap"><table><thead><tr><th>SQL</th><th>Datasource</th><th>Executions</th><th>Errors</th><th>Total time</th><th>Average</th><th>Slowest</th><th>Rows</th><th>Last execution</th></tr></thead><tbody id="sqlRows"></tbody></table></div></section>
<section id="slow" class="view"><div class="toolbar"><h2>Slow SQL samples</h2><span id="slowMeta" class="secondary"></span></div><div class="table-wrap"><table><thead><tr><th>Executed</th><th>Datasource</th><th>Operation</th><th>SQL template</th><th>Duration</th><th>Rows</th><th>Result</th><th>Error class</th><th>Trace ID</th></tr></thead><tbody id="slowRows"></tbody></table></div></section></main>
<script>
const state={db:null,sql:null,timer:null,descending:true,expanded:new Set()};const el=id=>document.getElementById(id);const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));const number=value=>Number(value||0).toLocaleString();const ms=value=>Number(value||0).toLocaleString(undefined,{maximumFractionDigits:2})+' ms';const time=value=>value?new Date(value).toLocaleString():'-';
function status(value){const cls=value==='SERVING'?'good':value==='DEGRADED'||value==='STALE'?'warn':'bad';return '<span class="status '+cls+'"><span class="dot"></span>'+esc(value)+'</span>'}function badge(op){const write=['INSERT','UPDATE','DELETE','CREATE','ALTER','DROP'].includes(op);return '<span class="badge '+(write?'write':'')+'">'+esc(op)+'</span>'}function result(failed){return '<span class="badge '+(failed?'failed':'success')+'">'+(failed?'FAILED':'SUCCESS')+'</span>'}function tone(value,kind){return '<span class="tone '+kind+'">'+value+'</span>'}function successCount(value){return tone(number(value),Number(value||0)>0?'good':'muted')}function errorCount(value,rate){const count=Number(value||0),text=number(count)+(rate===undefined?'':' ('+(Number(rate||0)*100).toFixed(1)+'%)');return tone(text,count>0?'bad':'muted')}function runningCount(value){return tone(number(value),Number(value||0)>0?'warn':'muted')}function latency(value){const duration=Number(value||0),threshold=Number(state.sql?.slow_threshold_ms||0);let kind='';if(threshold>0&&duration>=threshold)kind='bad';else if(threshold>0&&duration>=threshold/2)kind='warn';return tone(ms(duration),kind)}function buckets(value={}){return '<span class="buckets">'+[value.lt_1_ms,value.from_1_to_10_ms,value.from_10_to_100_ms,value.from_100_ms_to_1_s,value.from_1_to_10_s,value.gte_10_s].map(number).join(' / ')+'</span>'}
async function load(){try{const [db,sql]=await Promise.all([fetch('/debug/datasources',{cache:'no-store'}),fetch('/debug/sql',{cache:'no-store'})]);if(!db.ok||!sql.ok)throw new Error('Diagnostics request failed');const dbData=(await db.json()).data??{};const sqlData=(await sql.json()).data??{};state.db={...dbData,datasources:Array.isArray(dbData.datasources)?dbData.datasources:[]};state.sql={...sqlData,summary:sqlData.summary??{},operations:Array.isArray(sqlData.operations)?sqlData.operations:[],statements:Array.isArray(sqlData.statements)?sqlData.statements:[],slow_queries:Array.isArray(sqlData.slow_queries)?sqlData.slow_queries:[]};el('error').style.display='none';render()}catch(error){el('error').textContent=error.message;el('error').style.display='block'}}
function setSummary(id,html){el(id).innerHTML=html}function render(){const db=state.db,sql=state.sql,summary=sql.summary;el('state').innerHTML=status(db.status);setSummary('open',tone(number(db.datasources.reduce((n,d)=>n+d.pool.open_connections,0)),''));setSummary('inuse',runningCount(db.datasources.reduce((n,d)=>n+d.pool.in_use,0)));setSummary('running',runningCount(summary.running));setSummary('peak',tone(number(summary.concurrent_max),''));setSummary('tracked',tone(number(sql.tracked)+' / '+number(sql.capacity),''));setSummary('executions',tone(number(summary.executions),''));setSummary('errors',errorCount(summary.errors,summary.error_rate));setSummary('average',latency(summary.average_duration_ms));setSummary('slowcount',tone(number(sql.slow_queries.length)+' / '+number(sql.slow_capacity),sql.slow_queries.length>0?'warn':'muted'));el('checked').textContent='Checked '+time(db.checked_at);el('operationMeta').textContent='Since '+time(sql.statistics_since)+' | buckets: <1ms / 1-10ms / 10-100ms / 100ms-1s / 1-10s / >=10s';el('slowMeta').textContent='Threshold '+ms(sql.slow_threshold_ms);renderPools();renderOperations();renderSQL();renderSlow()}
function renderPools(){const rows=state.db.datasources.map(d=>'<tr><td><strong>'+esc(d.name)+'</strong></td><td>'+status(d.status)+'</td><td>'+(d.readable?'<span class="badge">READ</span> ':'')+(d.writable?'<span class="badge write">WRITE</span>':'')+'</td><td>'+number(d.pool.open_connections)+'</td><td>'+runningCount(d.pool.in_use)+'</td><td>'+number(d.pool.idle)+'</td><td>'+number(d.pool.max_open_connections)+'</td><td>'+number(d.pool.wait_count)+'</td><td>'+ms(d.pool.wait_duration_ms)+'</td><td>'+errorCount(d.consecutive_failures)+'</td></tr>');el('poolRows').innerHTML=rows.join('')||'<tr><td colspan="10" class="empty">No datasources</td></tr>'}
function renderOperations(){el('operationRows').innerHTML=state.sql.operations.map(s=>'<tr><td><strong>'+esc(s.datasource)+'</strong></td><td>'+badge(s.operation)+'</td><td>'+runningCount(s.running)+'</td><td>'+number(s.concurrent_max)+'</td><td>'+number(s.executions)+'</td><td>'+successCount(s.successes)+'</td><td>'+errorCount(s.errors,s.error_rate)+'</td><td>'+latency(s.minimum_duration_ms)+'</td><td>'+latency(s.average_duration_ms)+'</td><td>'+latency(s.max_duration_ms)+'</td><td>'+ms(s.total_duration_ms)+'</td><td>'+number(s.total_rows)+' / '+number(s.max_rows)+'</td><td>'+buckets(s.duration_buckets)+'</td><td>'+time(s.first_executed_at)+'</td><td>'+time(s.last_executed_at)+'</td></tr>').join('')||'<tr><td colspan="15" class="empty">No SQL operations</td></tr>'}
function sortValue(item,key){const value=item[key];return key.endsWith('_at')?(value?new Date(value).getTime():0):Number(value||0)}function sqlKey(s){return s.datasource+':'+s.fingerprint}function renderSQL(){const q=el('sqlFilter').value.toLowerCase(),key=el('sqlSort').value,direction=state.descending?-1:1;const items=state.sql.statements.filter(s=>(s.datasource+' '+s.operation+' '+(s.table||'')+' '+s.statement).toLowerCase().includes(q)).slice().sort((a,b)=>(sortValue(a,key)-sortValue(b,key))*direction);el('sqlRows').innerHTML=items.map(s=>{const id=sqlKey(s),open=state.expanded.has(id),lastError=s.last_error_class?tone(esc(s.last_error_class)+' at '+time(s.last_error_at),'bad'):tone('-','muted');return '<tr class="sql-main-row" data-sql-key="'+esc(id)+'" tabindex="0" aria-expanded="'+open+'"><td><div class="sql-cell"><button class="disclosure '+(open?'open':'')+'" type="button" tabindex="-1" aria-hidden="true">&#8250;</button>'+badge(s.operation)+'<span class="sql" title="'+esc(s.statement)+'">'+esc(s.statement)+'</span></div></td><td><strong>'+esc(s.datasource)+'</strong></td><td>'+number(s.executions)+'</td><td>'+errorCount(s.errors,s.error_rate)+'</td><td>'+ms(s.total_duration_ms)+'</td><td>'+latency(s.average_duration_ms)+'</td><td>'+latency(s.max_duration_ms)+'</td><td>'+number(s.total_rows)+'</td><td>'+time(s.last_executed_at)+'</td></tr><tr class="detail-row" data-sql-detail="'+esc(id)+'"'+(open?'':' hidden')+'><td colspan="9"><dl class="detail-grid"><div class="detail-item"><dt>Fingerprint</dt><dd class="sql">'+esc(s.fingerprint)+'</dd></div><div class="detail-item"><dt>Table</dt><dd>'+esc(s.table||'-')+'</dd></div><div class="detail-item"><dt>Successes</dt><dd>'+successCount(s.successes)+'</dd></div><div class="detail-item"><dt>Fastest</dt><dd>'+latency(s.minimum_duration_ms)+'</dd></div><div class="detail-item"><dt>Rows max</dt><dd>'+number(s.max_rows)+'</dd></div><div class="detail-item detail-wide"><dt>Latency buckets (&lt;1ms / 1-10ms / 10-100ms / 100ms-1s / 1-10s / &gt;=10s)</dt><dd>'+buckets(s.duration_buckets)+'</dd></div><div class="detail-item"><dt>First execution</dt><dd>'+time(s.first_executed_at)+'</dd></div><div class="detail-item"><dt>Last execution</dt><dd>'+time(s.last_executed_at)+'</dd></div><div class="detail-item"><dt>Last error</dt><dd>'+lastError+'</dd></div></dl></td></tr>'}).join('')||'<tr><td colspan="9" class="empty">No matching SQL statistics</td></tr>'}
function renderSlow(){el('slowRows').innerHTML=state.sql.slow_queries.map(s=>'<tr><td>'+time(s.executed_at)+'</td><td>'+esc(s.datasource)+'</td><td>'+badge(s.operation)+'</td><td class="sql" title="'+esc(s.statement)+'">'+esc(s.statement)+'</td><td>'+tone(ms(s.duration_ms),s.failed?'bad':'warn')+'</td><td>'+number(s.rows)+'</td><td>'+result(s.failed)+'</td><td>'+(s.error_class?tone(esc(s.error_class),'bad'):tone('-','muted'))+'</td><td class="sql">'+esc(s.trace_id||'-')+'</td></tr>').join('')||'<tr><td colspan="9" class="empty">No slow SQL samples</td></tr>'}
const viewNames=new Set(['pools','sql','slow','operations']);function viewFromURL(){const value=new URLSearchParams(location.search).get('view');return viewNames.has(value)?value:'sql'}function activateView(view,historyMode){if(!viewNames.has(view))view='sql';document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));if(historyMode){const url=new URL(location.href);url.searchParams.set('view',view);history[historyMode+'State']({view},'',url)}}document.querySelectorAll('.tab').forEach(button=>button.addEventListener('click',()=>activateView(button.dataset.view,'push')));window.addEventListener('popstate',()=>activateView(viewFromURL()));function toggleSQL(row){const key=row.dataset.sqlKey,open=!state.expanded.has(key);if(open)state.expanded.add(key);else state.expanded.delete(key);row.setAttribute('aria-expanded',String(open));row.querySelector('.disclosure').classList.toggle('open',open);const detail=row.nextElementSibling;if(detail&&detail.dataset.sqlDetail===key)detail.hidden=!open}el('sqlRows').addEventListener('click',event=>{const row=event.target.closest('[data-sql-key]');if(row)toggleSQL(row)});el('sqlRows').addEventListener('keydown',event=>{if(event.key!=='Enter'&&event.key!==' ')return;const row=event.target.closest('[data-sql-key]');if(row){event.preventDefault();toggleSQL(row)}});el('sqlFilter').addEventListener('input',()=>state.sql&&renderSQL());el('sqlSort').addEventListener('change',()=>state.sql&&renderSQL());el('sortDirection').addEventListener('click',()=>{state.descending=!state.descending;el('sortDirection').innerHTML=state.descending?'&#8595;':'&#8593;';el('sortDirection').title=state.descending?'Descending':'Ascending';el('sortDirection').setAttribute('aria-label',el('sortDirection').title);state.sql&&renderSQL()});el('refresh').addEventListener('click',load);el('interval').addEventListener('change',schedule);function schedule(){clearInterval(state.timer);const value=Number(el('interval').value);if(value)state.timer=setInterval(load,value)}activateView(viewFromURL(),'replace');schedule();load();
</script>
</body>
</html>`
